def count_lines_with_invoice(path):
    count = 0; line_has = False; carry = b""
    with open(path, "rb") as f:
        while True:
            chunk = f.read(1 << 20)
            if not chunk: break
            parts = (carry + chunk).split(b"\n")
            for i, line in enumerate(parts[:-1]):
                if b"invoice" in line or (i == 0 and line_has):
                    count += 1
            line_has = b"invoice" in parts[-1]
            carry = parts[-1][-6:]
    if line_has: count += 1
    return count

total = 0
for rel, p in files:
    try:
        n = count_lines_with_invoice(p); total += n
        print(f"{rel}: {n}")
    except OSError as e:
        print(f"{rel}: unreadable")
print("TOTAL", total)

